/*
 * A210600  Triangle of coefficients of polynomials u(n,x) jointly generated
 *          with A210601; see the Formula section.
 * https://oeis.org/A210600
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, tabl
 * Formula:   not stated
 * Range:     u8 n <= 23, u16 n <= 52, u32 n <= 52, u64 n <= 52, u128 n <= 52,
 *            big any n
 * Helpers:   row_number
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/*  Triangle of coefficients of polynomials u(n,x) generated by
 *
 *  u(1,x) = 1
 *  v(1,x) = 1
 *
 *  u(n,x) = x*u(n‑1,x) + (x+1)*v(n‑1,x) + 1
 *  v(n,x) = (x+1)*u(n‑1,x) + (x+1)*v(n‑1,x) + 1
 *
 *  a(n) is the (n‑1)th element of the flattened triangle
 *  (row‑by‑row, left‑to‑right, starting at a(1)=1).  The
 *  triangle rows correspond to the coefficients of u(n,x)
 *  in ascending powers of x.  The sequence satisfies the
 *  alternating row‑sum property 1,0,1,0,… described in the OEIS
 *  entry.  The code below memoises all rows that are needed
 *  and is O(m) in the number of rows required for the largest
 *  argument.
 */

#include <stddef.h>
#include <stdlib.h>
#include "../utils/row_number.h"

/*  Storage for the rows of coefficients of u and v.
 *
 *  u_rows[i][k]  = coefficient of x^k in u(i,x)
 *  v_rows[i][k]  = coefficient of x^k in v(i,x)
 *
 *  Rows are 1‑based; index 0 of the array is unused.
 */
static seq_t **u_rows = NULL;
static seq_t **v_rows = NULL;
static size_t max_row = 0;

/*  Ensure that all rows up to r are computed.  */
static void grow_to(size_t r)
{
    if (r <= max_row) return;

    if (max_row == 0) {
        u_rows = (seq_t **)malloc(2 * sizeof(seq_t *));
        v_rows = (seq_t **)malloc(2 * sizeof(seq_t *));
        u_rows[0] = NULL;
        v_rows[0] = NULL;
    } else {
        u_rows = (seq_t **)realloc(u_rows, (r + 1) * sizeof(seq_t *));
        v_rows = (seq_t **)realloc(v_rows, (r + 1) * sizeof(seq_t *));
    }

    /*  Initialize row 1.  */
    if (max_row < 1) {
        u_rows[1] = (seq_t *)malloc(sizeof(seq_t));
        v_rows[1] = (seq_t *)malloc(sizeof(seq_t));
        u_rows[1][0] = 1;
        v_rows[1][0] = 1;
        max_row = 1;
    }

    /*  Compute remaining rows.  */
    for (size_t i = max_row + 1; i <= r; ++i) {
        seq_t *new_u = (seq_t *)malloc(i * sizeof(seq_t));
        seq_t *new_v = (seq_t *)malloc(i * sizeof(seq_t));
        seq_t *prev_u = u_rows[i - 1];
        seq_t *prev_v = v_rows[i - 1];
        size_t prev_len = i - 1;

        /*  u(i,x) constant term (k=0).  */
        new_u[0] = prev_v[0] + 1;   /*  +1 in the recurrence  */

        /*  Remaining coefficients.  */
        for (size_t k = 1; k < i; ++k) {
            seq_t val = 0;
            if (k - 1 < prev_len) val += prev_u[k - 1];
            if (k - 1 < prev_len) val += prev_v[k - 1];
            if (k < prev_len)      val += prev_v[k];
            new_u[k] = val;
        }

        /*  v(i,x)  */
        new_v[0] = prev_u[0] + prev_v[0] + 1;  /*  +1 in the recurrence  */
        for (size_t k = 1; k < i; ++k) {
            seq_t val = 0;
            if (k - 1 < prev_len) val += prev_u[k - 1];
            if (k < prev_len)      val += prev_u[k];
            if (k - 1 < prev_len) val += prev_v[k - 1];
            if (k < prev_len)      val += prev_v[k];
            new_v[k] = val;
        }

        u_rows[i] = new_u;
        v_rows[i] = new_v;
    }
    max_row = r;
}

/*  Public function: return the n-th element of the sequence
 *  (Sequence A210600, OEIS offset 1).  */
seq_t a(idx_t n)
{
    if (n == 0) return 0;          /*  undefined for n<1  */

    /* Find the row containing the n-th term.  */
    size_t r = row_number(n);

    /* Make sure rows up to r are computed.  */
    grow_to(r);

    /* Compute how many terms precede row r.  */
    idx_t prev_sum = 0;
    for (size_t i = 1; i < r; ++i)
        prev_sum += (idx_t)i;

    /* Index within the row (0‑based).  */
    size_t pos = (size_t)(n - prev_sum - 1);

    return u_rows[r][pos];
}
